package com.tapeverify.copilot.dto;
import com.tapeverify.copilot.entity.Loan; import java.math.BigDecimal; import java.time.*;
/** Readable canonical state captured at the time of each audit event. */
public record AuditLoanSnapshotDto(String batchId,String sourceFileId,String sourceLoanId,String borrowerId,String borrowerName,BigDecimal principalAmount,BigDecimal currentBalance,BigDecimal interestRate,String paymentStatus,Integer daysPastDue,String borrowerState,String documentStatus,LocalDateTime lastUpdatedAt,String sourceSystem,LocalDate originationDate,LocalDate maturityDate,String status) { public static AuditLoanSnapshotDto from(Loan l){return new AuditLoanSnapshotDto(l.getBatchId(),l.getSourceFileId(),l.getSourceLoanId(),l.getBorrowerId(),l.getBorrowerName(),l.getPrincipalAmount(),l.getCurrentBalance(),l.getInterestRate(),l.getPaymentStatus(),l.getDaysPastDue(),l.getBorrowerState(),l.getDocumentStatus(),l.getLastUpdatedAt(),l.getSourceSystem(),l.getOriginationDate(),l.getMaturityDate(),l.getStatus().name());} }
